str.example:
let s = string_from("  Hello, Crumbs  ");
let t = s.trim();                         // "Hello, Crumbs" (a view, no copy)
println("{}", t.upper());                 // HELLO, CRUMBS
println("{}", t.find("Crumbs"));          // 7
let mut parts = "a,b,c".split(",");
println("{}", str.join(parts.view(), "-"));   // a-b-c
parts.release();

