async.example:
async fn square(n: i32) -> i32 { return n * n; }

fn main() {
    let a = square(6);          // starts right away, on its own thread
    let b = square(7);
    println("{}", await a + await b);   // 85
}

fmt.example:
struct Point { x: i32, y: i32 }

impl Display for Point {
    fn to_string(self) -> String { return format("({}, {})", self.x, self.y); }
}

fn main() {
    let p = Point { x: 1, y: 2 };
    println(p);                // (1, 2)
    println("at {p:>10}");     // at     (1, 2)
    println("{p:?}");          // Point { x: 1, y: 2 }
}
